/** Comparison table — Body Pod vs DEXA vs InBody vs cheap smart scale. */
function CompareTable() {
  const cols = ['Hume Body Pod', 'DEXA scan', 'Gym InBody', 'Cheap smart scale'];
  const rows: [string, string[]][] = [
    ['Where you use it', ['At home', 'Clinic, by appointment', 'At the gym', 'At home']],
    ['Cost', ['~$229 once', '~$100 each scan', 'Tied to membership', '$20–$50']],
    ['How often you can check', ['Daily / weekly', '1–2× a year', 'Only at the gym', 'Daily']],
    ['Separates fat vs. muscle', ['Yes', 'Yes', 'Yes', 'No']],
    ['Segmental (arms / legs / L-R)', ['Yes', 'Yes', 'Yes', 'No']],
    ['Visceral-fat trend', ['Yes', 'Yes', 'Sometimes', 'No']],
    ['Tracks the trend over time', ['Yes, in-app', 'Snapshot only', 'Limited', 'Weight only']],
    ['Radiation', ['None', 'Low-dose X-ray', 'None', 'None']],
  ];
  const cell = (v: string, hume: boolean) => {
    const yes = v === 'Yes';
    const no = v === 'No';
    return (
      <span className={`inline-flex items-center gap-1 ${hume ? 'font-semibold text-[#16181C]' : 'text-[#6B7078]'}`}>
        {yes && <span className="text-[#0C2442]">✓</span>}
        {no && <span className="text-[#C8BFAE]">—</span>}
        {!yes && !no && v}
        {yes && <span className="sr-only">Yes</span>}
      </span>
    );
  };
  return (
    <div className="overflow-x-auto rounded-2xl border border-[#E5E8EC]">
      <table className="w-full min-w-[640px] border-collapse text-left text-[14px] font-[Inter]">
        <thead>
          <tr>
            <th className="bg-[#F1F4F8] p-3" />
            {cols.map((c, i) => (
              <th
                key={c}
                className={`p-3 text-center align-bottom text-[13px] font-semibold ${
                  i === 0 ? 'bg-[#0C2442] text-white' : 'bg-[#F1F4F8] text-[#6B7078]'
                }`}
              >
                {c}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map(([label, vals]) => (
            <tr key={label} className="border-t border-[#EDEFF2]">
              <th className="p-3 text-[13px] font-medium text-[#41454C]">{label}</th>
              {vals.map((v, i) => (
                <td
                  key={i}
                  className={`p-3 text-center ${i === 0 ? 'bg-[#0C2442]/[0.06]' : ''}`}
                >
                  {cell(v, i === 0)}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/** Hero image carousel — 4 slides, autoplay + arrows + dots. */
function HeroCarousel() {
  const slides = [
    { file: 'hero-1.webp', title: 'Body Composition' },
    { file: 'hero-2.webp', title: 'Free App' },
    { file: 'hero-3.webp', title: 'Fat vs. muscle' },
    { file: 'hero-4.webp', title: 'Scan at home' },
  ];
  const [i, setI] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setI((p) => (p + 1) % slides.length), 4500);
    return () => clearInterval(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const go = (d: number) => setI((p) => (p + d + slides.length) % slides.length);
  return (
    <div>
      <div className="relative">
        <div className="overflow-hidden rounded-2xl border border-white/15">
          <div
            className="flex transition-transform duration-500 ease-out"
            style={{ transform: `translateX(-${i * 100}%)` }}
          >
            {slides.map((s) => (
              <div key={s.file} className="w-full shrink-0">
                <img
                  src={`${ASSET}images/hume/yaz/${s.file}`}
                  alt=""
                  aria-hidden
                  className="aspect-square w-full object-cover"
                />
              </div>
            ))}
          </div>
        </div>
        <button
          aria-label="Previous slide"
          onClick={() => go(-1)}
          className="absolute left-3 top-1/2 flex h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-lg text-[#16181C] shadow transition hover:bg-white"
        >
          ‹
        </button>
        <button
          aria-label="Next slide"
          onClick={() => go(1)}
          className="absolute right-3 top-1/2 flex h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-lg text-[#16181C] shadow transition hover:bg-white"
        >
          ›
        </button>
      </div>

      {/* Clickable thumbnails with titles (small) */}
      <div className="mt-3 flex gap-3">
        {slides.map((s, idx) => (
          <button
            key={s.file}
            onClick={() => setI(idx)}
            aria-label={s.title}
            className="w-16 shrink-0 text-center"
          >
            <span
              className={`block overflow-hidden rounded-lg border-2 transition ${
                i === idx ? 'border-[#B58A3B]' : 'border-white/20 hover:border-white/50'
              }`}
            >
              <img
                src={`${ASSET}images/hume/yaz/${s.file}`}
                alt=""
                aria-hidden
                className="aspect-square w-full object-cover"
              />
            </span>
            <span className="mt-1.5 block text-[9px] font-medium leading-tight text-white/70">
              {s.title}
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

